Let $(\alpha_k)_{k\in [K]}$ be as in Theorem~\ref{non_asymptotic_lower_bound_theorem}. For any policy $\pi$,
\begin{multline}
    \inf_{F\in \mathcal{F}_{[-1, 1]}^K} \left\{P_{(F_{1}, \ldots, F_{K})}(\tau(B, \pi)<\infty) - \exp\left(- (B+1)\sum_{k=1}^K \alpha_k \gamma(F_k)\right)\right\} <0 \\
    \implies \sup_{F\in \mathcal{F}_{[-1, 1]}^K} \left\{P_{(F_{1}, \ldots, F_{K})}(\tau(B, \pi)<\infty) - \exp\left(- (B+1)\sum_{k=1}^K \alpha_k \gamma(F_k)\right)\right\} >0. \label{lower_general}
\end{multline}
